--warm-beige: hsl(67, 50%, 86%);       // 卡片、容器背景
--warm-cornsilk: hsl(52, 94%, 94%);    // 高亮背景
--warm-papaya: hsl(43, 82%, 89%);      // 强调色、悬停状态
--warm-tea: hsl(74, 32%, 76%);         // 次要元素
```

