// 负责在前端即时切换浅色/温暖/深色/跟随系统模式

export type ThemeMode = 'system' | 'light' | 'warm' | 'dark'

export type EffectiveTheme = 'light' | 'warm' | 'dark'

interface ThemeState {
  mode: ThemeMode
  effective: EffectiveTheme
  mediaQuery?: MediaQueryList
  listener?: (event: MediaQueryListEvent) => void
}

const state: ThemeState = {
  mode: 'system',
  effective: 'light',
}

const THEME_CLASSES: EffectiveTheme[] = ['light', 'warm', 'dark']

function applyThemeClass(theme: EffectiveTheme) {
  const root = document.documentElement
  // 移除所有主题类
  root.classList.remove(...THEME_CLASSES)
  // 添加当前主题类（light模式不添加类，作为默认）
  if (theme !== 'light') {
    root.classList.add(theme)
  }
}

function cleanupListener() {
  if (state.mediaQuery && state.listener) {
    state.mediaQuery.removeEventListener('change', state.listener)
  }
  state.mediaQuery = undefined
  state.listener = undefined
}

export function applyTheme(mode: ThemeMode) {
  if (typeof window === 'undefined') return

